 public sealed class ActionInput{public Guid OperationId{get;set;}=Guid.NewGuid();[Required]public string Mode{get;set;}="release";public uint? ExpectedVersion{get;set;}public decimal Quantity{get;set;}[StringLength(500)]public string? Reason{get;set;}[Required,RegularExpression("^[0-9]{4,8}$")]public string Pin{get;set;}="";}
 public sealed class PlanningInput{public Guid OperationId{get;set;}=Guid.NewGuid();public uint ExpectedVersion{get;set;}public List<PlanningTargetInput> Targets{get;set;}=[];[StringLength(500)]public string? Reason{get;set;}[Required,RegularExpression("^[0-9]{4,8}$")]public string Pin{get;set;}="";}
 public sealed class PlanningTargetInput{public Guid PlanId{get;set;}public string? TargetKey{get;set;}}
 public sealed class MaterialInput{public Guid OperationId{get;set;}=Guid.NewGuid();public Guid StageId{get;set;}public uint ExpectedVersion{get;set;}public string Mode{get;set;}="consume";public List<MaterialLineInput> Lines{get;set;}=[];public Guid? DestinationLocationId{get;set;}public bool ApproveSharedDestination{get;set;}[StringLength(120)]public string? Reference{get;set;}[StringLength(500)]public string? Notes{get;set;}[Required,RegularExpression("^[0-9]{4,8}$")]public string Pin{get;set;}="";}
